{
 "command": "cat scripts/backfill_tax.py && ls",
 "description": "Show backfill script and repo layout"
}

{
 "command": "cat src/billing/periods.py; echo \"DATABASE_URL=${DATABASE_URL:-<unset>} BACKFILL_BATCH=${BACKFILL_BATCH:-<unset>}\"; grep -rn -i \"backfill\" README.md docs Makefile 2>/dev/null | head",
 "description": "Inspect month window helper, env, and docs"
}

{
 "command": "cat docs/ops/backfills.md; echo ---; python scripts/backfill_tax.py --month 2026-09; echo \"exit=$?\"",
 "description": "Read backfill docs and run September backfill"
}

{
 "command": "python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"; echo \"TZ=${TZ:-<unset>}\"; date +%Z",
 "description": "Run September backfill with safe batch size"
}

{
 "command": "TZ=UTC python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"",
 "description": "Dry-run September backfill under UTC"
}
